using Essco.Application.Inventory;using Essco.Domain.Inventory;namespace Essco.Tests.Unit.Inventory;public sealed class InventoryTests{[Fact]public async Task Count_rejects_negative_quantity(){var r=await new InventoryService(new Repo()).SaveCountAsync(new(1,"A",1,"I","Item",-1,false,"P"),default);Assert.False(r.Succeeded);Assert.Contains("La cantidad no puede ser negativa.",r.Errors);}[Fact]public async Task Group_requires_responsible_and_supplier(){var r=await new InventoryService(new Repo()).SaveGroupAsync(new(1,"A","","","",""),default);Assert.False(r.Succeeded);Assert.Equal(2,r.Errors.Count);}private sealed class Repo:IInventoryRepository{public ValueTask<IReadOnlyCollection<PhysicalInventory>>ListAsync(CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<PhysicalInventory>>([]);public ValueTask<PhysicalInventory?>GetAsync(int i,CancellationToken t)=>ValueTask.FromResult<PhysicalInventory?>(null);public ValueTask<IReadOnlyCollection<InventoryItem>>ListItemsAsync(int i,CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<InventoryItem>>([]);public ValueTask<IReadOnlyCollection<InventoryCount>>ListCountsAsync(int i,string?g,CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<InventoryCount>>([]);public ValueTask<bool>SaveCountAsync(InventoryCount c,CancellationToken t)=>ValueTask.FromResult(true);public ValueTask<IReadOnlyCollection<InventoryGroup>>ListGroupsAsync(int i,CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<InventoryGroup>>([]);public ValueTask<bool>SaveGroupAsync(InventoryGroup g,CancellationToken t)=>ValueTask.FromResult(true);public ValueTask<bool>DeleteGroupAsync(int i,string c,string s,CancellationToken t)=>ValueTask.FromResult(true);public ValueTask<bool>CloseAsync(int i,decimal e,decimal s,CancellationToken t)=>ValueTask.FromResult(true);}}
